-- Chronic-hunger stats by country over 60+ years -- undernourishment and food-insecurity scales.
-- Auto-generated by scripts/gen_evidence_pages.py: 279,470 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
-- grouped on year-like text/number column YEAR (NOT date-cast -- avoids the 8-digit epoch trap); LIMIT bounds it.
select "YEAR" as year, count(*) as records
from THE_LIBRARY.ECONOMY.FOOD_SECURITY_INDICATORS
group by 1
order by 1
limit 1000
